// Response/data types are generated from the Rust structs by ts-rs
// (src/bindings/, regenerated by `cargo test`); this file re-exports
// them and keeps the frontend-only types and the two input types whose
// double-option patch semantics do not map cleanly to a derive.

export type { AppConfig } from "./bindings/AppConfig";
export type { BirthdayEntry } from "./bindings/BirthdayEntry";
export type { BirthdayView } from "./bindings/BirthdayView";
export type { BirthdaysResult } from "./bindings/BirthdaysResult";
export type { ConfigError } from "./bindings/ConfigError";
export type { DashboardContext } from "./bindings/DashboardContext";
export type { DayContext } from "./bindings/DayContext";
export type { EngineOutcome } from "./bindings/EngineOutcome";
export type { JournalEntry } from "./bindings/JournalEntry";
export type { KbNode } from "./bindings/KbNode";
export type { KbSearchHit } from "./bindings/KbSearchHit";
export type { List } from "./bindings/List";
export type { RecurringResult } from "./bindings/RecurringResult";
export type { RecurringRule } from "./bindings/RecurringRule";
export type { ScheduleBlock } from "./bindings/ScheduleBlock";
export type { ScheduledEvent } from "./bindings/ScheduledEvent";
export type { Task } from "./bindings/Task";
export type { UpcomingResult } from "./bindings/UpcomingResult";

export type { ScheduledEvent as UpcomingEvent } from "./bindings/ScheduledEvent";

import type { Task } from "./bindings/Task";

export type Theme = "dark" | "light";
export type DoneDisplay = "inline" | "separate";
export type TaskStatus = Task["status"];

export type Section =
  | "dashboard"
  | "upcoming"
  | "calendar"
  | "journal"
  | "kb"
  | "settings";

export interface NewTask {
  title: string;
  description_md?: string;
  list_id?: number | null;
  scheduled_date?: string | null;
  time?: string | null;
  color?: string | null;
  parent_task_id?: number | null;
}

// A field set to null clears the column; an absent field is untouched.
export interface TaskPatch {
  title?: string;
  description_md?: string;
  list_id?: number | null;
  scheduled_date?: string | null;
  time?: string | null;
  status?: TaskStatus;
  color?: string | null;
  sort_order?: number;
}
